.ddb-footer {
    --common-0: #fff;
    --common-1000: #000;
    --grey-400: #a2acb2;
    --footer-background: #242527;

    margin-top: 20px;
    padding: 0;
    background: var(--common-1000);
    line-height: 21px;
}

.ddb-footer * {
    margin: 0;
    padding: 0;
}

.ddb-footer .ddb-footer__privacy-policy-notice {
    display: block;
    background: var(--common-1000);
    color: var(--grey-400);
    font-size: 15px;
    padding: 0.75rem 3.75rem;
    text-align: center;
    max-width: 1200px;
    margin: 0 auto;
}

a.ddb-footer__link,
a.ddb-footer__link:visited {
    font-size: 15px;
    color: var(--common-0);
    text-decoration: none;
}

a.ddb-footer__link:hover {
    color: var(--grey-400);
    text-decoration: none;
}

.ddb-footer__main {
    min-height: 265px;
    background: var(--footer-background);
}

.ddb-footer__main__container {
    max-width: 1440px;
    display: grid;
    justify-content: start;
    column-gap: 64px;
    grid-template-columns: repeat(5, auto);
    grid-template-rows: 1fr auto;
    margin: 0 auto;
    padding: 64px 48px;
}

.ddb-footer__main__header {
    margin-bottom: 4px;
    color: var(--grey-400);
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
}

.ddb-footer__main__header--socials {
    margin-bottom: 14px;
}

.ddb-footer__main__list {
    list-style-type: none;
}

.ddb-footer__main__list--horizontal {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
}

.ddb-footer__main__list--horizontal li {
    margin-right: 24px;
    margin-bottom: 10px;
}

.ddb-footer__main__list--horizontal li:last-of-type {
    margin-right: 0;
}

.ddb-footer__main__list-item--vertical {
    margin-bottom: 4px;
}

.ddb--footer__main__apps-icon {
  display: block;
  width: 7.375rem;
  margin-top: 0.625rem;
  margin-bottom: 0.5rem;
}

.ddb-footer__socials-main {
  box-sizing: border-box;
  justify-content: start;
  max-width: 90rem;
  margin: 0 auto;
  padding: 2.5rem 3rem 1.5rem 3.25rem;
}

.ddb-footer__social-icon {
  height: 1.45rem;
  margin-right: 0.10rem;
  margin-bottom: 0.625rem;
}

.ddb-footer__bottom {
    background: var(--common-1000);
    display: grid;
    grid-template-columns: 11fr auto auto 42px;
    grid-column-gap: 30px;
    box-sizing: border-box;
    max-width: 1440px;
    grid-template-rows: 1fr auto;
    align-content: center;
    align-items: center;
    padding: 14px 48px 16px;
    margin: 0 auto;
    color: var(--grey-400);
    font-size: 0.75rem;
}

.ddb-footer__bottom__text-container {
    max-width: 906px;
}

.ddb-footer__bottom__header {
    color: var(--grey-400);
    font-size: 12px;
    margin-bottom: 4px;
    font-weight: 700;
    text-transform: uppercase;
}

a.ddb-footer__bottom__link,
a.ddb-footer__bottom__link:visited,
a.ddb-footer__bottom__link:hover {
    color: var(--grey-400);
    font-size: 12px;
    font-weight: 700;
    text-decoration: none;
    text-transform: uppercase;
}

@media screen and (max-width: 480px) {
  .ddb-footer__social-icon {
    height: 1.2rem;
    margin-right: 0.2rem;
  }

  .ddb--footer__main__apps-icon {
    width: 9rem;
  }

  .ddb--footer__download-apps {
    grid-column: span 2;
  }
}

@media screen and (max-width: 1227px) {
    .ddb-footer__main__container {
        column-gap: 30px;
    }
}

@media screen and (max-width: 959px) {
    .ddb-footer__main__container {
        grid-template-columns: repeat(2, 1fr);
        grid-template-rows: auto auto;
        grid-column-gap: 2.5rem;
        column-gap: 40px;
        padding: 24px 52px;
    }

    .ddb-footer__main__list {
        margin-bottom: 24px;
    }

    .ddb-footer__main__list--apps {
        margin-bottom: 0;
    }

    .ddb-footer__main__container__logo-container {
        grid-column: span 2;
        place-self: center;
        margin-bottom: 34px;
    }

    .ddb-footer__main__header {
        margin-bottom: 12px;
    }

    .ddb-footer__main__header--socials {
        margin-bottom: 20px;
    }

    .ddb-footer__main__socials-container {
        grid-column: span 2;
    }

    .ddb-footer__bottom {
        min-height: 250px;
        grid-template-columns: auto auto;
        grid-template-rows: auto auto auto;
        align-content: start;
    }

    .ddb-footer__bottom__text-container {
        grid-column: span 2;
        margin-bottom: 24px;
    }

    .ddb-footer__bottom__header {
        margin-bottom: 16px;
    }

    .ddb-footer__bottom__esrb-logo-container {
        margin-top: 16px;
    }
}








